-- GENERATED from library blueprint by vyuh_blueprint. Do not edit.

CREATE SCHEMA IF NOT EXISTS library_runtime;

CREATE TABLE IF NOT EXISTS library_runtime.blueprint_revisions (
  id text PRIMARY KEY,
  blueprint_name text NOT NULL,
  blueprint_version text NOT NULL,
  status text NOT NULL DEFAULT 'installed',
  source jsonb NOT NULL DEFAULT '{}'::jsonb,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  installed_at timestamptz NOT NULL DEFAULT NULLIF(current_setting('vyuh.occurred_at', true), '')::timestamptz,
  recorded_sequence bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL
);

DO $sequence$
BEGIN
  IF to_regclass('library_runtime.blueprint_revisions') IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'library_runtime' AND table_name = 'blueprint_revisions'
      AND column_name = 'recorded_sequence') THEN
    ALTER TABLE library_runtime.blueprint_revisions DISABLE TRIGGER USER;
    ALTER TABLE library_runtime.blueprint_revisions ADD COLUMN recorded_sequence bigint;
    UPDATE library_runtime.blueprint_revisions t SET recorded_sequence = n.place
      FROM (SELECT ctid AS row, row_number() OVER (ORDER BY installed_at, id) AS place FROM library_runtime.blueprint_revisions) n
      WHERE t.ctid = n.row;
    ALTER TABLE library_runtime.blueprint_revisions ALTER COLUMN recorded_sequence SET NOT NULL;
    ALTER TABLE library_runtime.blueprint_revisions ALTER COLUMN recorded_sequence ADD GENERATED BY DEFAULT AS IDENTITY;
    PERFORM setval(pg_get_serial_sequence('library_runtime.blueprint_revisions', 'recorded_sequence'),
      (SELECT coalesce(max(recorded_sequence), 0) + 1 FROM library_runtime.blueprint_revisions), false);
    ALTER TABLE library_runtime.blueprint_revisions ENABLE TRIGGER USER;
  END IF;
END
$sequence$;

