CREATE OR REPLACE FUNCTION library_runtime.holds_contract_revision(revision_id text)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, library_runtime
AS $$ SELECT EXISTS (
  SELECT 1 FROM library_runtime.blueprint_revisions
  WHERE id = holds_contract_revision.revision_id
) $$;

REVOKE ALL ON FUNCTION library_runtime.holds_contract_revision(text) FROM PUBLIC;

CREATE TABLE IF NOT EXISTS library_runtime.query_reads (
  id text NOT NULL,
  request_id text NOT NULL,
  source text NOT NULL,
  actor_id text,
  tenant_id text,
  correlation_id text,
  module text NOT NULL,
  entity text NOT NULL,
  projection text NOT NULL,
  entity_id text,
  query_digest text NOT NULL,
  row_count integer NOT NULL,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  occurred_at timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT NULLIF(current_setting('vyuh.occurred_at', true), '')::timestamptz,
  PRIMARY KEY (occurred_at, id)
) PARTITION BY RANGE (occurred_at);

CREATE TABLE IF NOT EXISTS library_runtime.query_reads_undated PARTITION OF library_runtime.query_reads DEFAULT;

CREATE OR REPLACE FUNCTION library_runtime.add_query_read_month(p_month date)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, library_runtime
SET TimeZone = 'UTC'
AS $$
DECLARE
  v_from date := date_trunc('month', p_month)::date;
  v_to date := (date_trunc('month', p_month) + interval '1 month')::date;
  v_name text := 'query_reads' || '_' || to_char(p_month, 'YYYY_MM');
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('library_runtime.query_reads'));
  IF to_regclass(format('%I.%I', 'library_runtime_reads', v_name)) IS NOT NULL THEN
    RETURN;
  END IF;
  IF EXISTS (
    SELECT 1 FROM library_runtime.query_reads_undated
    WHERE occurred_at >= v_from AND occurred_at < v_to
  ) THEN
    RETURN;
  END IF;
  EXECUTE format('CREATE SCHEMA IF NOT EXISTS %I', 'library_runtime_reads');
  EXECUTE format(
    'CREATE TABLE %I.%I PARTITION OF library_runtime.query_reads FOR VALUES FROM (%L) TO (%L)',
    'library_runtime_reads', v_name, v_from, v_to
  );
END;
$$;

REVOKE ALL ON FUNCTION library_runtime.add_query_read_month(date) FROM PUBLIC;

CREATE OR REPLACE FUNCTION library_runtime.maintain_query_reads()
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, library_runtime
SET TimeZone = 'UTC'
AS $$
DECLARE
  v_table regclass;
BEGIN
  PERFORM library_runtime.add_query_read_month(now()::date);
  PERFORM library_runtime.add_query_read_month((now() + interval '1 month')::date);
  FOR v_table IN
    SELECT c.oid::regclass
    FROM pg_inherits i
    JOIN pg_class c ON c.oid = i.inhrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE i.inhparent = 'library_runtime.query_reads'::regclass
      AND n.nspname = 'library_runtime_reads'
      AND c.relname < 'query_reads' || '_' ||
        to_char(now() - interval '13 months', 'YYYY_MM')
  LOOP
    EXECUTE format('DROP TABLE %s', v_table);
  END LOOP;
END;
$$;

REVOKE ALL ON FUNCTION library_runtime.maintain_query_reads() FROM PUBLIC;

