CREATE SCHEMA IF NOT EXISTS durable_execution;

CREATE TABLE IF NOT EXISTS durable_execution.executions (
  id text PRIMARY KEY,
  definition_kind text NOT NULL,
  definition_key text NOT NULL,
  definition_digest text NOT NULL,
  status text NOT NULL,
  revision bigint NOT NULL DEFAULT 0 CHECK (revision >= 0),
  generation bigint NOT NULL DEFAULT 1 CHECK (generation > 0),
  input jsonb,
  output jsonb,
  failure jsonb,
  scope_key text,
  idempotency_key text,
  correlation_id text,
  parent_execution_id text REFERENCES durable_execution.executions(id) ON DELETE RESTRICT,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS durable_execution.events (
  id text PRIMARY KEY,
  execution_id text NOT NULL REFERENCES durable_execution.executions(id) ON DELETE RESTRICT,
  sequence bigint NOT NULL CHECK (sequence > 0),
  type text NOT NULL,
  occurred_at timestamptz NOT NULL,
  work_id text,
  attempt integer,
  payload jsonb,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE (execution_id, sequence)
);

CREATE TABLE IF NOT EXISTS durable_execution.work_items (
  id text PRIMARY KEY,
  execution_id text NOT NULL REFERENCES durable_execution.executions(id) ON DELETE RESTRICT,
  operation_key text NOT NULL,
  kind text NOT NULL,
  reference text NOT NULL,
  status text NOT NULL,
  attempt integer NOT NULL DEFAULT 1 CHECK (attempt > 0),
  idempotency_key text NOT NULL,
  payload jsonb,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL,
  available_at timestamptz NOT NULL,
  claimed_by text,
  claim_generation bigint NOT NULL DEFAULT 0 CHECK (claim_generation >= 0),
  lease_expires_at timestamptz,
  completed_at timestamptz,
  failure jsonb
);

CREATE TABLE IF NOT EXISTS durable_execution.signals (
  execution_id text NOT NULL REFERENCES durable_execution.executions(id) ON DELETE RESTRICT,
  name text NOT NULL,
  deduplication_key text NOT NULL,
  payload jsonb,
  received_at timestamptz NOT NULL,
  consumed_by text,
  consumed_at timestamptz,
  PRIMARY KEY (execution_id, name, deduplication_key)
);

CREATE TABLE IF NOT EXISTS durable_execution.effect_receipts (
  id text PRIMARY KEY,
  execution_id text NOT NULL REFERENCES durable_execution.executions(id) ON DELETE RESTRICT,
  work_id text NOT NULL REFERENCES durable_execution.work_items(id) ON DELETE RESTRICT,
  idempotency_key text NOT NULL UNIQUE,
  target text NOT NULL,
  status text NOT NULL,
  attempt_count integer NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  external_receipt jsonb,
  failure jsonb,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS durable_execution.dead_letters (
  id bigserial PRIMARY KEY,
  execution_id text NOT NULL REFERENCES durable_execution.executions(id) ON DELETE RESTRICT,
  work_id text NOT NULL REFERENCES durable_execution.work_items(id) ON DELETE RESTRICT,
  failure jsonb NOT NULL,
  attempt integer NOT NULL,
  created_at timestamptz NOT NULL,
  redriven_at timestamptz,
  redriven_by text
);

CREATE UNIQUE INDEX IF NOT EXISTS executions_scoped_idempotency_idx ON durable_execution.executions (COALESCE(scope_key, ''), definition_kind, definition_key, idempotency_key) WHERE idempotency_key IS NOT NULL;

CREATE INDEX IF NOT EXISTS executions_status_idx ON durable_execution.executions (status, updated_at);

CREATE INDEX IF NOT EXISTS executions_parent_idx ON durable_execution.executions (parent_execution_id) WHERE parent_execution_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS work_items_execution_idx ON durable_execution.work_items (execution_id, created_at);

CREATE INDEX IF NOT EXISTS work_items_claim_idx ON durable_execution.work_items (kind, status, available_at, created_at);

CREATE INDEX IF NOT EXISTS work_items_lease_idx ON durable_execution.work_items (lease_expires_at) WHERE status = 'claimed';

CREATE INDEX IF NOT EXISTS signals_unconsumed_idx ON durable_execution.signals (execution_id, received_at) WHERE consumed_by IS NULL;

CREATE INDEX IF NOT EXISTS effect_receipts_execution_idx ON durable_execution.effect_receipts (execution_id, updated_at);

CREATE INDEX IF NOT EXISTS effect_receipts_work_idx ON durable_execution.effect_receipts (work_id);

CREATE INDEX IF NOT EXISTS dead_letters_execution_idx ON durable_execution.dead_letters (execution_id, created_at);

CREATE INDEX IF NOT EXISTS dead_letters_work_idx ON durable_execution.dead_letters (work_id);

CREATE OR REPLACE FUNCTION durable_execution.reject_immutable_change()
RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'Durable execution history is immutable'
    USING ERRCODE = '23514';
END;
$$ LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

DROP TRIGGER IF EXISTS events_immutable ON durable_execution.events;

CREATE TRIGGER events_immutable BEFORE UPDATE OR DELETE ON durable_execution.events FOR EACH ROW EXECUTE FUNCTION durable_execution.reject_immutable_change();

CREATE OR REPLACE FUNCTION durable_execution.create_execution(p_execution jsonb, p_started jsonb)
RETURNS jsonb AS $$
DECLARE result jsonb;
BEGIN
  INSERT INTO durable_execution.executions (
    id, definition_kind, definition_key, definition_digest, status, revision,
    generation, input, output, failure, scope_key, idempotency_key,
    correlation_id, parent_execution_id, metadata, created_at, updated_at)
  VALUES (
    p_execution->>'id', p_execution#>>'{definition,kind}',
    p_execution#>>'{definition,key}', p_execution#>>'{definition,digest}',
    p_execution->>'status', (p_execution->>'revision')::bigint,
    (p_execution->>'generation')::bigint, p_execution->'input',
    p_execution->'output', p_execution->'failure', p_execution->>'scope_key',
    p_execution->>'idempotency_key', p_execution->>'correlation_id',
    p_execution->>'parent_execution_id', COALESCE(p_execution->'metadata','{}'),
    (p_execution->>'created_at')::timestamptz,
    (p_execution->>'updated_at')::timestamptz);
  INSERT INTO durable_execution.events (
    id, execution_id, sequence, type, occurred_at, work_id, attempt, payload, metadata)
  VALUES (
    p_started->>'id', p_started->>'execution_id',
    (p_started->>'sequence')::bigint, p_started->>'type',
    (p_started->>'occurred_at')::timestamptz, p_started->>'work_id',
    (p_started->>'attempt')::integer, p_started->'payload',
    COALESCE(p_started->'metadata','{}'));
  SELECT to_jsonb(e) INTO result FROM durable_execution.executions e
    WHERE e.id = p_execution->>'id';
  RETURN result;
END;
$$ LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION durable_execution.load_execution(p_execution_id text)
RETURNS jsonb AS $$
  SELECT CASE WHEN e.id IS NULL THEN NULL ELSE jsonb_build_object(
    'execution', to_jsonb(e),
    'history', COALESCE((SELECT jsonb_agg(to_jsonb(h) ORDER BY h.sequence)
      FROM durable_execution.events h WHERE h.execution_id = e.id), '[]'::jsonb),
    'work_items', COALESCE((SELECT jsonb_agg(to_jsonb(w) ORDER BY w.created_at)
      FROM durable_execution.work_items w WHERE w.execution_id = e.id), '[]'::jsonb)) END
  FROM durable_execution.executions e WHERE e.id = p_execution_id;
$$ LANGUAGE sql STABLE SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION durable_execution.commit_execution(
  p_execution_id text, p_expected_revision bigint, p_status text,
  p_events jsonb, p_work_items jsonb, p_output jsonb, p_failure jsonb)
RETURNS jsonb AS $$
DECLARE result jsonb;
BEGIN
  UPDATE durable_execution.executions SET status = p_status, revision = revision + 1,
    output = p_output, failure = p_failure, updated_at = COALESCE(NULLIF(current_setting('vyuh.occurred_at', true), '')::timestamptz, now())
  WHERE id = p_execution_id AND revision = p_expected_revision
  RETURNING to_jsonb(executions.*) INTO result;
  IF result IS NULL THEN
    RAISE EXCEPTION 'Durable execution revision conflict' USING ERRCODE = '40001';
  END IF;
  INSERT INTO durable_execution.events
    SELECT x.id, x.execution_id, x.sequence, x.type, x.occurred_at,
      x.work_id, x.attempt, x.payload, x.metadata
    FROM jsonb_to_recordset(COALESCE(p_events,'[]')) AS x(
      id text, execution_id text, sequence bigint, type text,
      occurred_at timestamptz, work_id text, attempt integer,
      payload jsonb, metadata jsonb);
  INSERT INTO durable_execution.work_items
    SELECT x.id, x.execution_id, x.operation_key, x.kind, x.reference,
      x.status, x.attempt, x.idempotency_key, x.payload, x.metadata,
      x.created_at, x.available_at, x.claimed_by, x.claim_generation,
      x.lease_expires_at, x.completed_at, x.failure
    FROM jsonb_to_recordset(COALESCE(p_work_items,'[]')) AS x(
      id text, execution_id text, operation_key text, kind text, reference text,
      status text, attempt integer, idempotency_key text, payload jsonb,
      metadata jsonb, created_at timestamptz, available_at timestamptz,
      claimed_by text, claim_generation bigint, lease_expires_at timestamptz,
      completed_at timestamptz, failure jsonb)
    ON CONFLICT (id) DO NOTHING;
  RETURN result;
END;
$$ LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

DROP FUNCTION IF EXISTS durable_execution.find_executions_needing_decision(integer);
DROP FUNCTION IF EXISTS durable_execution.find_executions_needing_decision(integer, text, text[]);

CREATE OR REPLACE FUNCTION durable_execution.find_executions_needing_decision(
  p_limit integer DEFAULT 100,
  p_definition_kind text DEFAULT NULL,
  p_definition_keys text[] DEFAULT '{}',
  p_decision_event_types text[] DEFAULT '{}')
RETURNS SETOF text AS $$
  SELECT e.id FROM durable_execution.executions e
  WHERE e.status NOT IN ('succeeded','failed','cancelled','compensated')
    AND (p_definition_kind IS NULL OR e.definition_kind = p_definition_kind)
    AND (cardinality(p_definition_keys) = 0 OR
      e.definition_key = ANY(p_definition_keys))
    AND EXISTS (
      SELECT 1 FROM durable_execution.work_items w
      WHERE w.execution_id = e.id
        AND w.status IN ('succeeded','failed')
        AND w.completed_at IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM durable_execution.events ev
          WHERE ev.execution_id = e.id AND ev.work_id = w.id
            AND ev.attempt = w.attempt
            AND (cardinality(p_decision_event_types) = 0 OR
              ev.type = ANY(p_decision_event_types))))
  ORDER BY e.updated_at LIMIT p_limit;
$$ LANGUAGE sql STABLE SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

DROP FUNCTION IF EXISTS durable_execution.claim_work(text, text, timestamptz, bigint, integer);

CREATE OR REPLACE FUNCTION durable_execution.claim_work(
  p_kind text, p_worker_id text, p_now timestamptz,
  p_lease_milliseconds bigint, p_limit integer DEFAULT 1,
  p_definition_keys text[] DEFAULT '{}')
RETURNS SETOF jsonb AS $$
BEGIN
  RETURN QUERY
  WITH candidates AS (
    SELECT w.id FROM durable_execution.work_items w
    JOIN durable_execution.executions e ON e.id = w.execution_id
    WHERE w.kind = p_kind AND w.available_at <= p_now
      AND (cardinality(p_definition_keys) = 0 OR
        e.definition_key = ANY(p_definition_keys))
      AND (w.status = 'pending' AND
        (w.metadata->>'expires_at' IS NULL OR
          (w.metadata->>'expires_at')::timestamptz > p_now) OR
        (w.status = 'claimed' AND w.lease_expires_at <= p_now))
    ORDER BY w.created_at FOR UPDATE OF w SKIP LOCKED LIMIT p_limit)
  UPDATE durable_execution.work_items w SET status = 'claimed', claimed_by = p_worker_id,
    claim_generation = claim_generation + 1,
    lease_expires_at = p_now + (p_lease_milliseconds * interval '1 millisecond')
  FROM candidates c WHERE w.id = c.id RETURNING to_jsonb(w.*);
END;
$$ LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION durable_execution.heartbeat_work(
  p_work_id text, p_worker_id text, p_claim_generation bigint,
  p_now timestamptz, p_lease_milliseconds bigint)
RETURNS void AS $$
BEGIN
  UPDATE durable_execution.work_items SET lease_expires_at =
    p_now + (p_lease_milliseconds * interval '1 millisecond')
  WHERE id = p_work_id AND status = 'claimed' AND claimed_by = p_worker_id
    AND claim_generation = p_claim_generation;
  IF NOT FOUND THEN RAISE EXCEPTION 'Durable work lease lost' USING ERRCODE='40001'; END IF;
END;
$$ LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION durable_execution.complete_work(
  p_work_id text, p_worker_id text, p_claim_generation bigint,
  p_output jsonb, p_completed_at timestamptz)
RETURNS jsonb AS $$
DECLARE result jsonb;
BEGIN
  UPDATE durable_execution.work_items SET status='succeeded', claimed_by=NULL,
    lease_expires_at=NULL, completed_at=p_completed_at,
    metadata=metadata || jsonb_build_object('output',p_output)
  WHERE id=p_work_id AND status='claimed' AND claimed_by=p_worker_id
    AND claim_generation=p_claim_generation RETURNING to_jsonb(work_items.*) INTO result;
  IF result IS NULL THEN RAISE EXCEPTION 'Durable work lease lost' USING ERRCODE='40001'; END IF;
  RETURN result;
END;
$$ LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION durable_execution.fail_work(
  p_work_id text, p_worker_id text, p_claim_generation bigint,
  p_failure jsonb, p_retry jsonb, p_failed_at timestamptz)
RETURNS jsonb AS $$
DECLARE current_attempt integer; retryable boolean; max_attempts integer;
DECLARE delay_ms bigint; result jsonb;
BEGIN
  SELECT attempt INTO current_attempt FROM durable_execution.work_items
    WHERE id=p_work_id AND status='claimed' AND claimed_by=p_worker_id
      AND claim_generation=p_claim_generation FOR UPDATE;
  IF current_attempt IS NULL THEN RAISE EXCEPTION 'Durable work lease lost' USING ERRCODE='40001'; END IF;
  retryable := COALESCE((p_failure->>'retryable')::boolean,false);
  max_attempts := COALESCE((p_retry->>'max_attempts')::integer,1);
  delay_ms := LEAST(
    COALESCE((p_retry->>'initial_delay_ms')::bigint,0) *
      power(COALESCE((p_retry->>'backoff_multiplier')::integer,1), current_attempt-1),
    COALESCE((p_retry->>'maximum_delay_ms')::bigint,0));
  UPDATE durable_execution.work_items SET
    status=CASE WHEN retryable AND current_attempt < max_attempts THEN 'pending' ELSE 'failed' END,
    attempt=CASE WHEN retryable AND current_attempt < max_attempts THEN current_attempt+1 ELSE current_attempt END,
    available_at=CASE WHEN retryable AND current_attempt < max_attempts
      THEN p_failed_at + (delay_ms * interval '1 millisecond') ELSE available_at END,
    claimed_by=NULL, lease_expires_at=NULL,
    completed_at=CASE WHEN retryable AND current_attempt < max_attempts THEN NULL ELSE p_failed_at END,
    failure=p_failure
  WHERE id=p_work_id RETURNING to_jsonb(work_items.*) INTO result;
  IF NOT (retryable AND current_attempt < max_attempts) THEN
    INSERT INTO durable_execution.dead_letters(execution_id,work_id,failure,attempt,created_at)
      SELECT execution_id,id,p_failure,current_attempt,p_failed_at FROM durable_execution.work_items WHERE id=p_work_id;
  END IF;
  RETURN result;
END;
$$ LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION durable_execution.fail_expired_pending_work(
  p_kind text, p_reference text, p_expired_at timestamptz,
  p_failed_at timestamptz, p_failure jsonb,
  p_definition_keys text[] DEFAULT '{}', p_limit integer DEFAULT 100)
RETURNS SETOF jsonb AS $$
BEGIN
  IF p_limit < 1 OR p_limit > 1000 THEN
    RAISE EXCEPTION 'Invalid stale work limit' USING ERRCODE='22023';
  END IF;
  RETURN QUERY
  WITH candidates AS (
    SELECT w.id FROM durable_execution.work_items w
    JOIN durable_execution.executions e ON e.id = w.execution_id
    WHERE w.kind = p_kind AND w.reference = p_reference
      AND w.status = 'pending'
      AND w.metadata->>'expires_at' IS NOT NULL
      AND (w.metadata->>'expires_at')::timestamptz <= p_expired_at
      AND e.status NOT IN ('succeeded','failed','cancelled','compensated')
      AND (cardinality(p_definition_keys) = 0 OR
        e.definition_key = ANY(p_definition_keys))
    ORDER BY w.created_at FOR UPDATE OF w SKIP LOCKED LIMIT p_limit)
  UPDATE durable_execution.work_items w SET status='failed', completed_at=p_failed_at,
    failure=p_failure
  FROM candidates c WHERE w.id = c.id RETURNING to_jsonb(w.*);
END;
$$ LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION durable_execution.cancel_work(
  p_execution_id text, p_operation_prefixes text[], p_cancelled_at timestamptz)
RETURNS integer AS $$
DECLARE affected integer;
BEGIN
  UPDATE durable_execution.work_items SET status='cancelled', claimed_by=NULL,
    lease_expires_at=NULL, completed_at=p_cancelled_at
  WHERE execution_id=p_execution_id AND status IN ('pending','claimed')
    AND EXISTS (
      SELECT 1 FROM unnest(p_operation_prefixes) prefix
      WHERE starts_with(operation_key, prefix));
  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END;
$$ LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION durable_execution.deliver_signal(p_signal jsonb)
RETURNS text AS $$
BEGIN
  INSERT INTO durable_execution.signals(execution_id,name,deduplication_key,payload,received_at,consumed_by)
  VALUES(p_signal->>'execution_id',p_signal->>'name',p_signal->>'deduplication_key',
    p_signal->'payload',(p_signal->>'received_at')::timestamptz,p_signal->>'consumed_by')
  ON CONFLICT (execution_id,name,deduplication_key) DO NOTHING;
  RETURN p_signal->>'execution_id';
END;
$$ LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION durable_execution.load_unconsumed_signals(p_execution_id text)
RETURNS SETOF jsonb AS $$
  SELECT to_jsonb(signals.*) FROM durable_execution.signals
  WHERE execution_id=p_execution_id AND consumed_by IS NULL ORDER BY received_at;
$$ LANGUAGE sql STABLE SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION durable_execution.redrive_execution(
  p_execution_id text, p_requested_by text, p_requested_at timestamptz, p_reason text)
RETURNS text AS $$
BEGIN
  UPDATE durable_execution.executions SET status='running', revision=revision+1,
    updated_at=p_requested_at,
    metadata=metadata || jsonb_build_object('redriven_by',p_requested_by,'redrive_reason',p_reason)
  WHERE id=p_execution_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown durable execution'; END IF;
  RETURN p_execution_id;
END;
$$ LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION durable_execution.record_effect_receipt(p_receipt jsonb)
RETURNS jsonb AS $$
DECLARE result jsonb;
BEGIN
  INSERT INTO durable_execution.effect_receipts(id,execution_id,work_id,idempotency_key,target,status,
    attempt_count,external_receipt,failure,metadata,updated_at)
  VALUES(p_receipt->>'id',p_receipt->>'execution_id',p_receipt->>'work_id',
    p_receipt->>'idempotency_key',p_receipt->>'target',p_receipt->>'status',
    (p_receipt->>'attempt_count')::integer,p_receipt->'external_receipt',
    p_receipt->'failure',COALESCE(p_receipt->'metadata','{}'),
    (p_receipt->>'updated_at')::timestamptz)
  ON CONFLICT (idempotency_key) DO NOTHING;
  SELECT to_jsonb(r) INTO result FROM durable_execution.effect_receipts r
    WHERE r.idempotency_key=p_receipt->>'idempotency_key';
  RETURN result;
END;
$$ LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION durable_execution.find_effect_receipt(p_idempotency_key text)
RETURNS jsonb AS $$
  SELECT to_jsonb(r) FROM durable_execution.effect_receipts r WHERE idempotency_key=p_idempotency_key;
$$ LANGUAGE sql STABLE SECURITY INVOKER
SET search_path = pg_catalog, pg_temp;

